    if pointer == "":
        return document
    if pointer[0] == "/":
        pointer = pointer[1:]
    parts = []
    i = 0
    n = len(pointer)
    current = ""
    while i < n:
        if pointer[i] == "/":
            parts.append(current)
            current = ""
            i += 1
        elif pointer[i] == "~":
            if i + 1 < n:
                if pointer[i+1] == "0":
                    current += "~"
                    i += 2
                elif pointer[i+1] == "1":
                    current += "/"
                    i += 2
                else:
                    current += pointer[i]
                    i += 1
            else:
                current += "~"
                i += 1
        else:
            current += pointer[i]
            i += 1
    parts.append(current)
    current_doc = document
    for part in parts:
        if isinstance(current_doc, dict):
            if part not in current_doc:
                raise KeyError(f"Key {part} not found")
            current_doc = current_doc[part]
        elif isinstance(current_doc, list):
            try:
                idx = int(part)
            except ValueError:
                raise KeyError(f"List index {part} is not an integer")
            if idx < 0 or idx >= len(current_doc):
                raise KeyError(f"List index {idx} out of range")
            current_doc = current_doc[idx]
        else:
            raise KeyError(f"Invalid type for segment {part}")
    return current_doc

